/**
 * v3.0 chunk 24: pre-generation at Idle, on the workspace harness (port 4175) loaded with
 * `?pregeneration=on`, its phrases generated by the real worker. Background attempts (the
 * `generate` calls carrying an abort signal while no session runs) are observed through the
 * harness's call records and held at its background gate, so each case is deterministic: a
 * session spends the ready phrases instead of requesting them, a player request or Start cancels
 * a held attempt and never waits for it, a change of the queue's key discards the ready phrases
 * (a tempo change keeps them), a window crossing that steps the density down discards the
 * phrases made at the wider density, nothing runs while a review shows, and no record is stored.
 */
import { expect, test, type Page } from '@playwright/test'

import { harnessSnapshot, queueSeeds, queueSessionSeeds } from '../release/harness-helpers'
import { expectIdleReady, expectReviewShowing } from '../review/review-helpers'
import { toBarline } from '../session/rolling-helpers'
import {
  phraseAction,
  sessionAction,
  sessionState,
  startSession,
  toRunning,
} from '../session/session-helpers'
import { databaseRecords } from '../storage/storage-helpers'
import { radio } from './helpers'
import {
  QUEUE_SIZE,
  backgroundCounts,
  generationRecords,
  gotoPregenerationHarness,
  holdBackground,
  phraseOfSeed,
  playerOrSessionRecordsFrom,
  readyWithSessionSeed,
  releaseBackground,
  untilBackgroundHeld,
  untilQueueFull,
} from './pregeneration-helpers'

/** The session seed every phrase 1 here is published with, unless a test queues another. */
const SESSION_SEED = 4242
/** The session seed a replaced phrase 1 is published with. */
const NEXT_SESSION_SEED = 5353

/** Intent: the phrase numbers the records' seeds belong to under `sessionSeed`, in order. */
function phrasesOf(
  page: Page,
  sessionSeed: number,
  records: readonly WorkspaceHarnessGenerationRequest[],
): Promise<(number | null)[]> {
  return Promise.all(records.map((record) => phraseOfSeed(page, sessionSeed, record.seed)))
}

/** Intent: the record of the call with request id `requestId`. */
async function recordOf(page: Page, requestId: string): Promise<WorkspaceHarnessGenerationRequest> {
  const record = (await generationRecords(page)).find((entry) => entry.requestId === requestId)
  if (record === undefined) throw new Error(`no generate call ${requestId}`)
  return record
}

/**
 * Intent: wait until the session, started after call index `from`, has requested phrase 2 itself
 * (a call carrying a signal, no background attempt), and return that request.
 */
async function sessionRequestForPhraseTwo(
  page: Page,
  from: number,
  sessionSeed: number,
): Promise<WorkspaceHarnessGenerationRequest> {
  await expect
    .poll(async () => (await playerOrSessionRecordsFrom(page, from)).some((r) => r.signal), {
      timeout: 30_000,
    })
    .toBe(true)
  const request = (await playerOrSessionRecordsFrom(page, from)).find((record) => record.signal)!
  expect(await phraseOfSeed(page, sessionSeed, request.seed)).toBe(2)
  return request
}

/** Intent: wait until Idle shows a phrase 1 other than `timeline` and a session can start. */
async function untilNewPhraseOne(page: Page, timeline: string | null): Promise<void> {
  await expect
    .poll(async () => (await harnessSnapshot(page)).timeline, { timeout: 30_000 })
    .not.toBe(timeline)
  await expectIdleReady(page)
  await expect(sessionAction(page)).toBeEnabled()
}

/** Intent: the page's other storage areas now: both Storage areas, Cache Storage and cookies. */
function otherStorageNow(page: Page) {
  return page.evaluate(async () => ({
    localStorage: Object.keys(localStorage),
    sessionStorage: Object.keys(sessionStorage),
    caches: await caches.keys(),
    cookie: document.cookie,
  }))
}

// @test-link [[req_idle_pregeneration]]
// @test-link [[module_idle_pregeneration_queue]]
test('at Idle up to four phrases are pre-generated and a session spends them', async ({ page }) => {
  test.setTimeout(120_000)
  await gotoPregenerationHarness(page)
  await readyWithSessionSeed(page, SESSION_SEED)

  const queued = await untilQueueFull(page)
  expect(queued).toHaveLength(QUEUE_SIZE)
  expect(await phrasesOf(page, SESSION_SEED, queued)).toEqual([2, 3, 4, 5])
  expect(queued.every((record) => record.signal && record.carryIn)).toBe(true)
  const startedAt = (await generationRecords(page)).length

  await startSession(page)
  const atStart = await sessionState(page)
  expect(atStart.latestReady).toBeGreaterThanOrEqual(2)
  expect(atStart.systems.bottom).toBe('2:whole')
  await toBarline(page, 3, 0)
  await sessionAction(page).click()

  const { lastHistoryPhrases } = await sessionState(page)
  expect(lastHistoryPhrases?.slice(1).map((phrase) => phrase.timeline)).toEqual([
    queued[0]!.timeline,
    queued[1]!.timeline,
  ])
  expect((await generationRecords(page)).slice(startedAt).filter((r) => r.signal)).toEqual([])
})

// @test-link [[rule_pregeneration_yields_to_player]]
// @test-link [[module_idle_pregeneration_queue]]
test('a regeneration cancels the background attempt in flight and never waits for it', async ({
  page,
}) => {
  await gotoPregenerationHarness(page)
  await holdBackground(page)
  await readyWithSessionSeed(page, SESSION_SEED)
  const held = await untilBackgroundHeld(page)
  const before = (await harnessSnapshot(page)).timeline
  const from = (await generationRecords(page)).length

  await queueSeeds(page, [8])
  await queueSessionSeeds(page, [NEXT_SESSION_SEED])
  await phraseAction(page).click()
  await untilNewPhraseOne(page, before)

  expect((await recordOf(page, held.requestId)).settled).toBe('cancelled')
  const [regeneration] = await playerOrSessionRecordsFrom(page, from)
  expect(regeneration).toMatchObject({ signal: false, background: false, settled: 'answered' })
  // The new phrase 1 came while background attempts were still held: its own one waits now.
  const next = await untilBackgroundHeld(page, from)
  expect(await phraseOfSeed(page, NEXT_SESSION_SEED, next.seed)).toBe(2)
})

// @test-link [[rule_start_never_waits_for_pregeneration]]
// @test-link [[rule_pregeneration_yields_to_player]]
test('Start pressed while a background attempt runs starts at once and cancels it', async ({
  page,
}) => {
  await gotoPregenerationHarness(page)
  await holdBackground(page)
  await readyWithSessionSeed(page, SESSION_SEED)
  const held = await untilBackgroundHeld(page)
  const from = (await generationRecords(page)).length

  await startSession(page)

  expect((await recordOf(page, held.requestId)).settled).toBe('cancelled')
  const phraseTwo = await sessionRequestForPhraseTwo(page, from, SESSION_SEED)
  expect(phraseTwo.background).toBe(false)
  expect((await backgroundCounts(page)).held).toBe(0)
})

/** One change of the queue's key at Idle, and what the next background request carries. */
interface KeyChange {
  readonly name: string
  /** The session seed phrase 1 holds after the change. */
  readonly sessionSeed: number
  readonly apply: (page: Page) => Promise<void>
  readonly expectCarried: (request: WorkspaceHarnessGenerationRequest) => void
}

/** Intent: click `option` of the radiogroup `group`, then wait for the new phrase 1. */
async function switchAndRegenerate(page: Page, group: string, option: string): Promise<void> {
  const before = (await harnessSnapshot(page)).timeline
  await queueSeeds(page, [8])
  await queueSessionSeeds(page, [NEXT_SESSION_SEED])
  await radio(page, group, option).click()
  await untilNewPhraseOne(page, before)
}

const KEY_CHANGES: readonly KeyChange[] = [
  {
    name: 'a control change',
    sessionSeed: SESSION_SEED,
    apply: async (page) => {
      await radio(page, 'Contour', 'Falling').click()
      await expect(radio(page, 'Contour', 'Falling')).toHaveAttribute('aria-checked', 'true')
    },
    expectCarried: (request) => expect(request.controls.contour).toBe('Falling'),
  },
  {
    name: 'a profile change',
    sessionSeed: SESSION_SEED,
    apply: async (page) => {
      await radio(page, 'Musical profile preset', 'Jazz').click()
      await expect(radio(page, 'Musical profile preset', 'Jazz')).toHaveAttribute(
        'aria-checked',
        'true',
      )
    },
    expectCarried: (request) => expect(request.musicalProfile.musicalProfile).toBe('Jazz'),
  },
  {
    name: 'an instrument change',
    sessionSeed: NEXT_SESSION_SEED,
    apply: (page) => switchAndRegenerate(page, 'Instrument profile', 'E-flat alto saxophone'),
    expectCarried: (request) => expect(request.controls.instrumentProfileId).toBe('eb-alto'),
  },
  {
    name: 'a regeneration',
    sessionSeed: NEXT_SESSION_SEED,
    apply: async (page) => {
      const before = (await harnessSnapshot(page)).timeline
      await queueSeeds(page, [8])
      await queueSessionSeeds(page, [NEXT_SESSION_SEED])
      await phraseAction(page).click()
      await untilNewPhraseOne(page, before)
    },
    expectCarried: () => undefined,
  },
]

for (const change of KEY_CHANGES) {
  // @test-link [[rule_pregeneration_discarded_on_change]]
  test(`${change.name} discards the ready phrases`, async ({ page }) => {
    test.setTimeout(90_000)
    await gotoPregenerationHarness(page)
    await readyWithSessionSeed(page, SESSION_SEED)
    await untilQueueFull(page)
    await holdBackground(page)
    const from = (await generationRecords(page)).length

    await change.apply(page)

    const restarted = await untilBackgroundHeld(page, from)
    expect(await phraseOfSeed(page, change.sessionSeed, restarted.seed)).toBe(2)
    change.expectCarried(restarted)
    const startedAt = (await generationRecords(page)).length
    await startSession(page)
    const phraseTwo = await sessionRequestForPhraseTwo(page, startedAt, change.sessionSeed)
    change.expectCarried(phraseTwo)
  })
}

// @test-link [[rule_pregeneration_discarded_on_change]]
test('a tempo change keeps the ready phrases', async ({ page }) => {
  await gotoPregenerationHarness(page)
  await readyWithSessionSeed(page, SESSION_SEED)
  await untilQueueFull(page)
  const from = (await generationRecords(page)).length

  await page.getByRole('button', { name: 'Increase tempo' }).click()
  await expect(page.getByRole('spinbutton', { name: 'Tempo' })).not.toHaveAttribute(
    'aria-valuenow',
    '90',
  )
  await startSession(page)

  const state = await sessionState(page)
  expect(state.sessionTempo).toBeGreaterThan(90)
  expect(state.latestReady).toBeGreaterThanOrEqual(2)
  expect(await generationRecords(page).then((records) => records.slice(from))).toEqual([])
})

// @test-link [[rule_pregeneration_discarded_on_change]]
// @test-link [[module_idle_pregeneration_queue]]
test('a window change that steps the density down discards the wider phrases', async ({ page }) => {
  test.setTimeout(90_000)
  await gotoPregenerationHarness(page)
  await radio(page, 'Note density', 'Sixteenth').click()
  await readyWithSessionSeed(page, SESSION_SEED)
  const queued = await untilQueueFull(page)
  expect(queued.map((record) => record.controls.noteDensity)).toEqual(Array(4).fill('Sixteenth'))
  await holdBackground(page)
  const from = (await generationRecords(page)).length

  await page.setViewportSize({ width: 1000, height: 700 })

  const restarted = await untilBackgroundHeld(page, from)
  expect(restarted.controls.noteDensity).toBe('Eighth')
  await expectIdleReady(page)
  const startedAt = (await generationRecords(page)).length
  await startSession(page)
  const phraseTwo = await sessionRequestForPhraseTwo(page, startedAt, SESSION_SEED)
  expect(phraseTwo.controls.noteDensity).toBe('Eighth')
})

// @test-link [[req_idle_pregeneration]]
// @test-link [[module_idle_pregeneration_queue]]
test('nothing is pre-generated while a review shows', async ({ page }) => {
  test.setTimeout(90_000)
  await gotoPregenerationHarness(page)
  await readyWithSessionSeed(page, SESSION_SEED)
  await untilQueueFull(page)
  await startSession(page)
  await toRunning(page)

  await queueSessionSeeds(page, [NEXT_SESSION_SEED])
  await sessionAction(page).click()
  await expectReviewShowing(page, 1)
  const stoppedAt = (await generationRecords(page)).length
  await expectIdleReady(page)
  expect((await generationRecords(page)).slice(stoppedAt).filter((r) => r.signal)).toEqual([])

  await sessionAction(page).click()
  await expect(sessionAction(page)).toHaveText('Start session')
  await untilQueueFull(page, stoppedAt)
})

// @test-link [[req_idle_pregeneration]]
test('pre-generation writes nothing to storage', async ({ page }) => {
  await gotoPregenerationHarness(page)
  await holdBackground(page)
  await readyWithSessionSeed(page, SESSION_SEED)
  await untilBackgroundHeld(page)
  const recordsBefore = await databaseRecords(page)
  const otherBefore = await otherStorageNow(page)

  await releaseBackground(page)
  await untilQueueFull(page)

  // The app's database may exist (it is opened at every load); the queue filling changes no
  // record in any of its stores, and the other storage areas stay empty.
  expect(Object.keys(recordsBefore)).toHaveLength(7)
  expect(await databaseRecords(page)).toEqual(recordsBefore)
  expect(await otherStorageNow(page)).toEqual(otherBefore)
  expect(otherBefore).toEqual({ localStorage: [], sessionStorage: [], caches: [], cookie: '' })
})
